import{_ as t,l as i,o as e,c as l,v as o,p as C,x as r,d as n,i as P,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"RoCE 与无损网络","description":"","frontmatter":{"title":"RoCE 与无损网络","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/roce-lossless.md","filePath":"cs/roce-lossless.md","lastUpdated":1789023840000}'),c={name:"cs/roce-lossless.md"};function p(E,a,h,R,D,A){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="roce-与无损网络" tabindex="-1">RoCE 与无损网络 <a class="header-anchor" href="#roce-与无损网络" aria-label="Permalink to &quot;RoCE 与无损网络&quot;">​</a></h1><div class="epigraph"><p>RDMA 把远程内存操作放到网卡，绕过内核；RoCEv2 用 UDP/IP 承载，依赖 PFC 等把以太网做成「不丢」的假象。</p><footer>—— 据 InfiniBand 架构对照；RoCEv2 规范；IEEE 802.1Qbb 实践整理</footer></div><p><a href="/cs/pause-pfc">PFC</a> 与 <a href="/cs/dctcp">DCTCP</a> 已给反压与浅队列。<a href="/cs/dctcp">上一课</a> 仍是 TCP。缺口是 <strong>RoCE</strong>：网卡 QP、无损以太网、与 TCP 栈对照。本课结束转发面课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>存储与 GPU 集合通信要微秒级、低 CPU。<a href="/cs/socket-api">套接字</a> 系统调用与拷贝太重。RDMA：RNIC 直接读写对端内存。InfiniBand 原生有基于信用的链路；RoCEv2 把 IB 运输装进 UDP，走 IP Clos——但 UDP 不重传，丢包让 QP 停顿昂贵，于是要 PFC 无损 + 可选 DCQCN。这是把端到端可靠性下放到链路与网卡，Saltzer 警告的那种优化：一旦无损失败，没有 TCP 兜底。</p><p>不要把 RoCE 写成「更快的 TCP」：语义是 RDMA，不是字节流。</p><p><span class="marginnote">RoCEv2 目的端口 4791。PFC 死锁与暂停风暴是已知运营风险。本课不写 verbs API 全集。</span></p><h3 id="rdma-怕丢" tabindex="-1">RDMA 怕丢 <a class="header-anchor" href="#rdma-怕丢" aria-label="Permalink to &quot;RDMA 怕丢&quot;">​</a></h3><p>RoCEv2 走 UDP/IP，靠 PFC/DCQCN 维持无损假象。失败恢复昂贵。语义不是字节流。留在数据中心。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：TCP 拷贝 vs RNIC 零拷贝。画：应用注册内存 → QP → RoCEv2 包 → PFC 队列。VXLAN 上跑 RoCE 要内层无损与外层 DSCP 映射，困难。</p>',11)),(e(),C(d,null,{default:r(()=>[P(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20APP%5B%22%E6%B3%A8%E5%86%8C%E5%86%85%E5%AD%98%22%5D%20--%3E%20RNIC%5B%22RNIC%20QP%22%5D%0A%20%20RNIC%20--%3E%20UDP%5B%22RoCEv2%20over%20IP%22%5D%0A%20%20UDP%20--%3E%20PFC%5B%22%E4%BC%98%E5%85%88%E7%BA%A7%E6%9A%82%E5%81%9C%22%5D%0A%20%20DROP%5B%22%E4%BB%8D%E4%B8%A2%E5%88%99%20QP%20%E6%98%82%E8%B4%B5%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>incast 对 RoCE 更致命，故 PFC+ECN。HOL：PFC 整类暂停会冻无关 QP。ECMP 乱序对 RDMA 不友好，常要保序或网卡重排。MTU 用巨帧摊头。与 5G URLLC 对照：都是用资源换尾延迟，一层在机房以太网，一层在空口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 iWARP 的全部。AIMD 与 Chiu–Jain 是下一单元第一课。后课默认：RoCE 依赖无损与网卡卸载；失败模式与 TCP 不同。</p><p>互联网广域不假设 PFC，RoCE 留在数据中心。</p><p>上一课留下的缺口在本课收口；「RoCE 与无损网络」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/aimd-dynamics">AIMD 与 Chiu–Jain</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RoCEv2：RDMA over UDP/IP，怕丢。</li><li>PFC/DCQCN 维持无损假象，有暂停风险。</li><li>不替代公网 TCP。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RoCEv2；802.1Qbb；InfiniBand 对照。</li></ul>',9))])}const m=t(c,[["render",p]]);export{f as __pageData,m as default};
